"""Explain ordinary wait, timeout boundaries and cleanup."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1445': ('음식이 준비될 때까지 기다리되 알림을 받으면 다시 확인합니다. 불렀다는 사실과 음식이 준비됐다는 사실은 같지 않습니다.', '시간 제한 없는 대기의 성공과 신호 중단 반환값을 구별합니다.', '조건 거짓 → schedule → 다시 거짓 → schedule → 참 → finish → 0을 그리세요. 별도로 허용된 신호 때문에 중단하면 -EINTR이라고 적으세요.', ['rcuwait_wait_event는 시간을 몇 칸만 기다리겠다는 제한을 주지 않는 대기입니다. 공통 매크로에 초기 반환값 0과 대기 명령 schedule()을 전달합니다. 반환값은 호출한 코드에 결과를 알려 주는 숫자입니다.', '조건이 참이면 반복을 끝내고 준비했던 0을 반환합니다. 여기서 0은 조건 성공입니다. 시간 제한 버전에서는 0이 만료를 뜻하므로, 함수 이름과 약속을 함께 읽어야 합니다. 모든 함수의 0이 같은 뜻은 아닙니다.', '조건이 거짓이면 지정한 대기 상태에서 중단을 허용하는 신호가 있는지 봅니다. 그런 신호가 있으면 -EINTR을 기록하고 끝냅니다. 신호는 작업에게 전달하는 알림이고, -EINTR은 신호 때문에 기다림을 중단했다는 오류 코드입니다.', '조건도 거짓이고 중단할 신호도 없다면 schedule로 다른 작업이 CPU를 사용할 기회를 줍니다. 다시 실행되면 반복문 위에서 조건부터 확인합니다. 깨어났다는 이유만으로 성공값을 돌려주는 것이 아닙니다.', '예를 들어 세 번 검사한 결과가 거짓·거짓·참이면 두 번 대기 명령을 거친 뒤 성공합니다. 이 예시는 흐름을 따라가는 연습입니다. 실제로 언제 다시 실행되는지는 스케줄러와 다른 작업의 진행에 따라 달라집니다.', '조건 성공과 신호 중단 모두 반복문 뒤의 finish_rcuwait로 갑니다. 이 정리는 등록된 task를 NULL로 바꾸고 현재 태스크의 대기 상태를 해제합니다. 일반 대기에는 남은 timeout을 양수로 돌려주는 약속이 없습니다.'], [('시간 제한 없는 rcuwait_wait_event에서 조건을 만족하면 반환값은?', ['항상 남은 시간 5예요', '0이에요'], '이 버전은 초기 반환값을 0으로 놓고 조건 성공 때 그대로 돌려줍니다. 시간 제한을 받지 않으므로 남은 시간 5를 반환한다는 답은 맞지 않습니다.'), ('schedule에서 돌아왔으면 조건을 확인하지 않고 성공할까요?', ['아니요. 반복문에서 조건을 다시 확인해요', '네. 깨우기는 조건을 자동으로 참으로 만들어요'], '다시 실행될 기회를 얻은 것과 필요한 조건이 맞는 것은 다릅니다. 조건이 여전히 거짓이면 다시 기다릴 수 있으므로 wake가 자동 성공이라는 답은 틀립니다.')]), 'os1446': ('기다릴 시간이 0이더라도 음식이 이미 준비돼 있으면 성공입니다. 준비되지 않은 채 시간이 끝난 경우와 구별해서 표시해야 합니다.', '시간 제한 대기의 0과 양수 반환값, 즉시 반환 경로를 배웁니다.', '시간 0·조건 거짓 → 0, 시간 0·조건 참 → 1, 시간 5·조건 참 → 5를 적으세요. 세 경우 모두 바깥 검사에서 끝날 수 있습니다.', ['timeout은 기다릴 시간의 한도입니다. 이 커널 API에서는 시간 단위가 jiffy이므로 숫자 5를 무조건 5초라고 읽으면 안 됩니다. 올바른 음수 아닌 시간 값을 전달해야 합니다. 남은 시간을 __ret라는 지역 변수로 관리합니다.', '바깥 rcuwait_wait_event_timeout은 대기자 등록 전에 조건과 시간부터 확인합니다. 이미 끝낼 수 있으면 내부 대기로 들어가지 않습니다. 그래서 이 함수 이름에 wait가 있어도 모든 호출이 잠드는 것은 아닙니다.', '___wait_cond_timeout은 조건을 __cond에 저장합니다. 조건이 참이고 남은 시간이 0이면 __ret를 1로 고칩니다. 성공과 만료를 모두 0으로 표시하면 구별할 수 없으므로, 이 경계의 성공에는 1이라는 표시를 남깁니다.', '조건이 거짓이고 시간도 0이면 반환값은 0입니다. 더 기다릴 시간도 없고 조건도 맞지 않으므로 바로 만료로 끝납니다. 이 바깥 경로는 prepare로 task를 등록하거나 schedule로 기다릴 필요가 없습니다.', '조건이 이미 참이고 시간이 5라면 5를 그대로 반환합니다. 시간 0·조건 참이면 1을 반환하므로, 반환값 1이 언제나 정확히 한 jiffy가 남았다는 뜻은 아닙니다. 이 값에는 경계에서 성공했다는 표시 역할도 있습니다.', '조건이 거짓이고 시간이 남아 있을 때 내부 대기로 갑니다. 정상 사용에서 최종 0은 만료, 양수는 조건 성공, -EINTR은 허용되는 신호로 인한 중단입니다. 시간 제한 없는 버전의 성공값 0과 섞어 외우지 마세요.'], [('초기 timeout이 0인데 조건은 이미 참이면 무엇을 반환할까요?', ['항상 만료를 뜻하는 0이에요', '성공을 구별하는 1이에요'], '조건 도우미가 참인 조건과 0을 함께 보면 반환값을 1로 바꿉니다. 시간이 0이라는 이유만으로 이미 맞는 조건까지 실패로 처리하지 않습니다.'), ('초기 시간 0, 조건 거짓일 때도 반드시 대기자를 등록할까요?', ['아니요. 바깥 검사에서 바로 0으로 끝날 수 있어요', '네. 반드시 등록하고 schedule까지 실행해요'], '바깥 검사에서 이미 만료를 알 수 있어 내부 대기를 건너뜁니다. 따라서 prepare나 schedule을 모든 호출이 거친다는 설명은 틀립니다.')]), 'os1447': ('기다릴 기회를 다섯 칸 받았다고 생각해 봅시다. 두 칸을 썼으면 남은 세 칸으로 다시 기다립니다. 마지막 칸이 끝나는 때에도 준비됐는지 확인합니다.', '반복 대기의 남은 시간 갱신과 만료·신호·성공 판정 순서를 이해합니다.', '남은 시간 5 → 대기 후 3 → 대기 후 0을 적으세요. 마지막 조건이 거짓이면 0, 참이면 1을 반환한다고 두 갈래로 나누세요.', ['실제로 기다리는 내부 매크로는 __ret를 처음 timeout으로 준비하고 대기자를 등록합니다. condition을 그대로 쓰지 않고 ___wait_cond_timeout으로 감싸서 조건 성공뿐 아니라 시간 만료도 반복을 끝내는 이유로 검사합니다.', '기다릴 차례에는 __ret = schedule_timeout(__ret)를 실행합니다. 지금 남은 시간을 넘기고, 돌아온 남은 시간을 다시 __ret에 저장하는 식입니다. 예를 들어 5에서 3이 됐다면 다음 대기는 3을 사용합니다. 매번 처음의 5로 되돌려 무한히 연장하지 않습니다.', '시간이 0이 되어 돌아와도 조건을 한 번 더 확인합니다. 조건이 거짓이면 0으로 끝납니다. 조건이 참이면 도우미가 0을 1로 바꿔 성공을 표시합니다. 마지막 경계에서 성공을 놓치지 않으려는 규칙입니다.', '반복문은 조건·만료 도우미를 신호 검사보다 먼저 실행합니다. 그래서 조건이 참이면 성공이 먼저이고, 조건이 거짓이어도 시간이 이미 0이면 만료가 먼저입니다. 시간이 남아 있고 조건이 거짓일 때만 다음 신호 검사로 넘어갑니다.', '그때 대기 상태가 허용하는 중단 신호가 있으면 __ret를 -EINTR로 바꾸고 반복을 끝냅니다. “조건이 거짓이면 신호가 항상 우선”이라고 외우면 만료 0의 경우를 놓칩니다. 위에서 어떤 검사로 이미 빠져나갔는지 확인하세요.', '내부 대기를 시작했다면 성공·만료·신호 중단 모두 finish_rcuwait로 정리합니다. task 등록을 지우고 현재 상태를 TASK_RUNNING으로 돌립니다. 조건식은 여러 번 읽을 수 있으므로 검사할 때마다 물건을 하나씩 없애는 식의 뜻하지 않은 부작용을 넣지 않아야 합니다.'], [('대기 후 남은 시간 0인 순간 조건이 참이면 반환값은?', ['언제나 실패 0이에요', '조건 성공을 나타내는 1이에요'], '마지막 조건도 검사하고, 참이면 도우미가 0을 1로 조정합니다. 만료 시점과 겹쳤다는 이유만으로 성공을 지우지 않습니다.'), ('내부 대기에서 신호로 중단돼도 finish 정리를 할까요?', ['네. 반복을 빠져나온 뒤 공통 정리를 해요', '아니요. task 포인터를 계속 남겨 둬요'], '신호 분기의 break는 반복문만 끝냅니다. 그다음 finish_rcuwait를 실행하므로 등록과 상태를 정리합니다. 신호 때문에 정리를 건너뛰는 코드는 아닙니다.')]), 'os1448': ('대기 명단에서 이름을 지우는 것은 그 사람 자체를 없애는 일이 아닙니다. 기다림을 끝낸 뒤에는 이름표와 대기 상태를 모두 정리해야 합니다.', '대기 등록 해제와 태스크 상태 복구를 객체 메모리 해제와 구별합니다.', '등록 중: task=A, 대기 상태 → finish → task=NULL, TASK_RUNNING을 적으세요. 옆에 “A와 rcuwait의 메모리를 free하는 함수는 아님”이라고 쓰세요.', ['finish_rcuwait는 기다림을 끝낼 때 쓰는 정리 함수입니다. 두 문장을 실행합니다. 첫 문장은 대기자 포인터를 비우고, 둘째 문장은 현재 작업의 대기 상태를 되돌립니다. 각각 다른 기록을 정리합니다.', 'rcu_assign_pointer(w->task,NULL)은 w 안의 task 항목에 대상 없음이라는 표시를 넣습니다. 이제 이 등록 칸은 현재 대기자를 가리키지 않습니다. NULL이라는 값을 저장하는 것이며 task_struct나 w 자체의 공간을 반납하는 것이 아닙니다.', '__set_current_state(TASK_RUNNING)은 지금 함수를 실행하는 태스크의 상태를 실행 가능 상태로 돌립니다. 여기서 current는 현재 작업입니다. TASK_RUNNING이라는 이름을 보고 앞으로 계속 CPU를 독점한다거나 절대 다시 기다리지 않는다는 뜻으로 읽으면 안 됩니다.', 'prepare는 현재 작업의 주소를 등록하고 finish는 그 등록을 끝내는 짝입니다. 직접 이 둘을 사용하는 코드도 정상 완료뿐 아니라 중단 경로에서 정리를 놓치지 않아야 합니다. 공통 대기 매크로는 반복문 뒤에 finish를 둡니다.', '같은 w에 대한 prepare와 finish의 쓰기는 호출자의 외부 규약으로 충돌하지 않게 해야 합니다. A가 끝내는 중에 B가 같은 칸에 등록하면 A가 B의 주소까지 지울 수 있습니다. RCU 대입이라는 이름만으로 한 명씩 사용한다는 조건이 사라지지 않습니다.', '등록을 지웠다고 과거에 포인터를 읽은 다른 CPU의 사용까지 전부 끝났다는 증거는 아닙니다. active가 거짓인 것을 봤다는 사실만으로 메모리를 즉시 없애도 된다고 결정하면 안 됩니다. 실제 객체 해제에는 해당 객체의 수명과 동기화 규칙을 따로 적용해야 합니다.'], [('finish_rcuwait가 w->task에 넣는 값은?', ['current를 계속 유지해요', 'NULL을 넣어요'], 'RCU 포인터 대입으로 등록을 끝내므로 NULL입니다. current를 남기면 대기자 등록이 남습니다. NULL 저장 자체는 태스크의 메모리 해제가 아닙니다.'), ('finish가 현재 태스크에 설정하는 상태는?', ['TASK_RUNNING이에요', '항상 TASK_UNINTERRUPTIBLE이에요'], '대기에서 나오는 작업의 상태를 TASK_RUNNING으로 복구합니다. TASK_UNINTERRUPTIBLE은 대기에 쓰일 수 있는 상태이므로 종료 정리의 최종 설정과 다릅니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_357.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
